<script setup lang="ts">
import {ref,computed,watch} from 'vue';
import type {Config,Spec} from './catalog';
import {subName} from './ru';
const props=defineProps<{config:Config,spec?:Spec,typeId:number,api:(path:string,method?:string,body?:unknown)=>Promise<any>}>();
const code=ref(''),entries=ref<any[]>([]),value=ref(''),label=ref(''),error=ref(''),busy=ref(false),opened=ref(false);
const codes=computed(()=>props.spec?.subfields.length?props.spec.subfields.filter(s=>!(props.config.local&&props.config.tag==='990'&&['d','e','f'].includes(s.code))).map(s=>({code:s.code,label:props.spec?.local?s.label:subName(props.config.tag,s.code,s.label)})):[{code:'_',label:'Значение поля'}]);
const selected=computed(()=>code.value||codes.value[0]?.code||'_');
const settings=computed(()=>props.config.vocabularies?.[selected.value]);
const visible=computed(()=>entries.value.filter(e=>e.tag===props.config.tag&&e.code===selected.value));
function toggle(enabled:boolean){props.config.vocabularies??={};if(enabled)props.config.vocabularies[selected.value]={auto_add:false,allow_edit:false};else delete props.config.vocabularies[selected.value];}
async function load(){if(!props.typeId)return;try{entries.value=await props.api('/types/'+props.typeId+'/vocabulary');}catch(e){error.value=String(e);}}
async function add(){error.value='';busy.value=true;try{await props.api(`/types/${props.typeId}/vocabulary/${props.config.tag}/${selected.value}`,'POST',{value:value.value,label:label.value});value.value='';label.value='';await load();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function remove(id:number){error.value='';busy.value=true;try{await props.api(`/types/${props.typeId}/vocabulary/${id}`,'DELETE');await load();}catch(e){error.value=String(e);}finally{busy.value=false;}}
watch(()=>props.typeId,()=>{entries.value=[];if(opened.value)load();});
</script>
<template><details class="subfield-settings vocabulary-settings" @toggle="opened=($event.target as HTMLDetailsElement).open;if(opened)load()"><summary>Справочники значений <span v-if="Object.keys(config.vocabularies||{}).length">· {{Object.keys(config.vocabularies||{}).length}}</span></summary><label>Строка<select :value="selected" :aria-label="'Строка справочника '+config.tag" @change="code=($event.target as HTMLSelectElement).value"><option v-for="s in codes" :value="s.code">{{s.code==='_'?'':('$'+s.code+' · ')}}{{s.label}}</option></select></label><label class="check-label"><input type="checkbox" :checked="!!settings" :aria-label="'Использовать справочник '+config.tag+'$'+selected" @change="toggle(($event.target as HTMLInputElement).checked)">Использовать справочник</label><template v-if="settings"><label class="check-label"><input type="checkbox" v-model="settings.allow_edit" :aria-label="'Разрешить редактирование '+config.tag+'$'+selected">Разрешить редактирование выбранного значения</label><label class="check-label"><input type="checkbox" v-model="settings.auto_add" :aria-label="'Автопополнение '+config.tag+'$'+selected">Автоматически добавлять новые значения</label><p>{{settings.auto_add?'Ручной ввод и выбор из списка. Новое значение добавляется после сохранения записи.':settings.allow_edit?'Можно выбрать и изменить значение или ввести своё. Изменения сохраняются только в записи, без изменения справочника.':'Только выбор из списка. Прежние значения существующих записей сохраняются.'}}</p><p>Сначала нажмите «Сохранить настройки», затем добавляйте значения. Отключение справочника не удаляет его содержимое.</p><p v-if="config.tag==='097'&&selected==='b'">ФИО берутся из активных пользователей системы. Список обновляется автоматически.</p><div v-if="typeId&&!(config.tag==='097'&&selected==='b')" class="vocabulary-add"><input v-model="value" maxlength="1000" placeholder="Значение, например 3" :aria-label="'Новое значение '+config.tag+'$'+selected"><input v-model="label" maxlength="1000" placeholder="Пояснение, например Общественные науки" :aria-label="'Пояснение '+config.tag+'$'+selected"><button :disabled="busy||!value.trim()" @click="add">Добавить значение</button></div><p v-if="!typeId">Сохраните новый тип документа для добавления значений.</p><p v-if="error" role="alert">{{error}}</p><div class="vocabulary-options"><div v-for="e in visible" :key="e.id" class="vocabulary-entry"><strong>{{e.value}}</strong><span>{{e.label}}</span><button v-if="!e.managed" :disabled="busy" :aria-label="'Убрать из справочника '+e.value" @click="remove(e.id)">×</button></div><p v-if="!visible.length">Значений пока нет.</p></div></template></details></template>
